import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"A1 Public Evidence Pack: Response Loss and Per-Tool Idempotency","description":"","frontmatter":{"title":"A1 Public Evidence Pack: Response Loss and Per-Tool Idempotency","date":"2026-08-28","updated":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"evidence-pack","edition":"research-center","summary":"Preserves the V2.0.4 response-loss historical contrast and adds sources and boundaries for the V2.1.2 creation-receipt implementation, independent QA and formal release.","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/research/evidence/2026-08-28-response-loss-idempotency.md","filePath":"en/research/evidence/2026-08-28-response-loss-idempotency.md","lastUpdated":1788145971000}'),r={name:"en/research/evidence/2026-08-28-response-loss-idempotency.md"};function n(o,e,d,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<p><a href="/joinwell52/zh/research/evidence/2026-08-28-response-loss-idempotency">中文版本</a></p><h1 id="a1-response-loss-and-per-tool-idempotency" tabindex="-1">A1 | Response Loss and Per-Tool Idempotency <a class="header-anchor" href="#a1-response-loss-and-per-tool-idempotency" aria-label="Permalink to &quot;A1 | Response Loss and Per-Tool Idempotency&quot;">​</a></h1><h2 id="claim" tabindex="-1">Claim <a class="header-anchor" href="#claim" aria-label="Permalink to &quot;Claim&quot;">​</a></h2><p>Under the same V2.0.4 fault window — “the action was persisted, then the success response was lost” — the tested <code>write_report</code> path reused the existing report, while the tested task-creation path produced a second task. This is a historical result, not current V2.1.2 behavior; the newer engineering result is documented below.</p><h2 id="re-runnable-public-attachments" tabindex="-1">Re-runnable public attachments <a class="header-anchor" href="#re-runnable-public-attachments" aria-label="Permalink to &quot;Re-runnable public attachments&quot;">​</a></h2><p>The Reader/check below replays consistency assertions over frozen JSON material. It does not call the private Runtime and does not replace product fault injection. To preserve historical auditability, the attachments and their digests are not rewritten as V2.1.2 output.</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A1-response-loss-fixture.json">Sanitized fixture</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A1-response-loss-reader.mjs">Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/A1-response-loss-check.mjs">Check script</a></li><li><a href="/joinwell52/assets/evidence/2026-08-28-runtime-boundary/MANIFEST.txt">Attachment SHA-256 manifest</a></li></ul><p>Download the three files into the same directory and run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node A1-response-loss-check.mjs</span></span></code></pre></div><p>Expected output:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;evidence_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RBE-20260828-A1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;report_objects_after_retry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;task_objects_after_retry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PASS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="source-and-boundary" tabindex="-1">Source and boundary <a class="header-anchor" href="#source-and-boundary" aria-label="Permalink to &quot;Source and boundary&quot;">​</a></h2><p>The original targeted experiment ran against CodeFlowMu V2.0.4 fixed commit <code>2ba1ad9baf27077861b6a20e5815b4175f0a81c6</code>. The public fixture replaces task identifiers, paths and body text while preserving the same commit declaration and final object-count relation.</p><p>It does not provide production incidence, cover untested tools, or by itself prove that the later creation-receipt implementation exists.</p><h2 id="_2026-08-30-v2-1-2-delivered-update" tabindex="-1">2026-08-30: V2.1.2 delivered update <a class="header-anchor" href="#_2026-08-30-v2-1-2-delivered-update" aria-label="Permalink to &quot;2026-08-30: V2.1.2 delivered update&quot;">​</a></h2><p>A pre-fix rerun on V2.1.1 fixed commit <code>36e5c83b</code> confirmed that the task-creation gap still existed while the <code>write_report</code> protection still held. Implementation commit <code>3302ca61</code> added a persistent receipt, the <code>write-task-v1</code> semantic digest, <code>reserved → task_created → committed</code> recovery, typed conflict handling, legacy compatibility and read-only stale-reservation diagnostics.</p><p>Independent QA on <code>64f633ac</code> observed:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Observation</th></tr></thead><tbody><tr><td>A2 response-loss retry</td><td>TASK count 1; same task_id; second call <code>reused / action_taken=false</code></td></tr><tr><td>A4 eight-way concurrency</td><td><code>created=1 / reused=7</code>; one task_id; TASK count 1</td></tr></tbody></table><p>A2/A4 are internal acceptance scenario identifiers, not the numbering scheme of this A1 public evidence pack. Process restart, digest conflict and intermediate-state recovery have separate targeted development records and are not automatically proven by those two independent-QA cases.</p><h2 id="sources-for-the-newer-claims-and-review-visibility" tabindex="-1">Sources for the newer claims and review visibility <a class="header-anchor" href="#sources-for-the-newer-claims-and-review-visibility" aria-label="Permalink to &quot;Sources for the newer claims and review visibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Claim</th><th>First-party source</th><th>Visibility</th></tr></thead><tbody><tr><td>Pre-fix reproduction, receipt implementation and development regression</td><td><code>RUNTIME-BOUNDARY-20260830-001</code>: phase0, targeted and full-regression records</td><td>Restricted mother-repository material</td></tr><tr><td>A2/A4 independent results</td><td><code>RUNTIME-BOUNDARY-QA-20260830-001</code>: independent-qa records</td><td>Restricted mother-repository material</td></tr><tr><td>Release tests passed</td><td><code>V2.1.2-R3</code>; Runtime 1842 pass / 0 fail / 1 skip, Shell 1037 pass / 0 fail</td><td>Restricted mother-repository material</td></tr><tr><td>Tag, artifacts and formal release</td><td><code>V2.1.2-PUBLICATION-20260830-001</code>; tagged source <code>cb8869a3</code>, main <code>919c3b48</code> after receipt</td><td>First-party release receipt, 2026-08-30</td></tr></tbody></table><p>The <a href="/joinwell52/en/research/evidence/2026-08-30-codeflowmu-v2.1.2-public-release-summary">CodeFlowMu V2.1.2 Public Release Summary</a> consolidates publicly citable version facts, the three Runtime boundary changes, final validation, compatibility and remaining limitations. Complete source code, raw QA logs and release receipts remain restricted first-party material and are not public reading links. This page also does not present the historical fixture pack as a new-version end-to-end reproduction kit.</p><p>The new guarantee requires the caller to reuse a stable <code>client_submission_id</code> with the same semantic digest. Legacy calls without an ID remain compatible but do not receive the stronger cross-response-loss/process guarantee. Formal release also does not imply that any particular online instance has already upgraded, and it does not include Open Edition.</p><p>The Windows symlink-permission skip, existing dependency-audit warnings, Python targeted-fixture SDK environment warning, and untested real LAN/Gateway and production-project scope remain explicit. Failed R1/R2 release evidence was not overwritten by the final R3 pass.</p>',24)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
